    print(f"Type: {tensor.dtype}")
    print(f"Contents:\n{tensor}")

def analyze_maze_structure(maze_file):
    torch.serialization.add_safe_globals([('__main__', 'Maze')])
    maze = torch.load(maze_file, weights_only=False)
    print("\nMaze attributes:")
    for attr_name in dir(maze):
        if not attr_name.startswith('_'):
            attr = getattr(maze, attr_name)
            print(f"{attr_name}: {type(attr)} = {attr}")

            # If it's a tensor, print more details
            if isinstance(attr, torch.Tensor):
                print_tensor_info(attr)

            # If it's a buffer or parameter, try to access it
            if hasattr(maze, '_buffers') and attr_name in maze._buffers:
                print(f"Buffer {attr_name}:", maze._buffers[attr_name])
            if hasattr(maze, '_parameters') and attr_name in maze._parameters:
                print(f"Parameter {attr_name}:", maze._parameters[attr_name])

    return maze

if __name__ == "__main__":
    maze_file = "ctf_files/attachment/maze.pt"
    maze = analyze_maze_structure(maze_file)
