import torch
import hashlib
from collections import deque

class Maze(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.L = None

def find_positions(grid):
    start = None
    end = None
    for i in range(grid.shape[0]):
        for j in range(grid.shape[1]):
            if grid[i][j] == 2:
                start = (i, j)
            elif grid[i][j] == 3:
                end = (i, j)
    return start, end

def get_moves(pos, grid):
    moves = []
    directions = [
        (-1, 0, 'W'),  # up
        (1, 0, 'S'),   # down
        (0, -1, 'A'),  # left
        (0, 1, 'D')    # right
    ]
    for dx, dy, move in directions:
        new_x, new_y = pos[0] + dx, pos[1] + dy
        if (0 <= new_x < grid.shape[0] and 
            0 <= new_y < grid.shape[1] and 
            grid[new_x][new_y] != 1):
            moves.append((new_x, new_y, move))
    return moves

def bfs_shortest_path(grid, start, end):
    queue = deque([(start[0], start[1], "")])
    visited = {(start[0], start[1])}

    while queue:
        x, y, path = queue.popleft()
        if (x, y) == (end[0], end[1]):
            return path

        for new_x, new_y, move in get_moves((x, y), grid):
            if (new_x, new_y) not in visited:
                visited.add((new_x, new_y))
                queue.append((new_x, new_y, path + move))

    return None

def solve_maze(maze_file):
    # Load maze
    torch.serialization.add_safe_globals([('__main__', 'Maze')])
    maze = torch.load(maze_file, weights_only=False)

    # Get the maze grid from the weights of the linear layer
    grid = maze.maze.weight.data
    print("Maze shape:", grid.shape)

    # Find start (2) and end (3) positions
    start, end = find_positions(grid)
    print(f"Start position: {start}")
    print(f"End position: {end}")

    # Find shortest path
    path = bfs_shortest_path(grid, start, end)
    print(f"Shortest path: {path}")

    # Calculate flag
    if path:
        flag = "flag{" + hashlib.md5(path.encode()).hexdigest() + "}"
        return flag
    return None

if __name__ == "__main__":
    maze_file = "ctf_files/attachment/maze.pt"
    flag = solve_maze(maze_file)
    if flag:
        print(f"Found flag: {flag}")
